/**
 * @title Invoices table with column picker and row actions
 * @description Choose which columns to show, a "More" menu on each row, status badges, a totals row and export. Scrolls sideways inside its frame on small screens.
 * @route /invoices
 * @height 820
 */
import { SidebarInset, SidebarProvider } from "@/components/ui/sidebar";
import { DashboardSidebar } from "@/components/dashboard-sidebar";
import { SiteHeader } from "@/components/site-header";
import { InvoicesTable } from "@/components/invoices-table";

export default function Page() {
  return (
    <SidebarProvider>
      <DashboardSidebar current="Reports" />
      <SidebarInset>
        <SiteHeader crumbs={[{ label: "Reports", href: "#" }, { label: "Invoices" }]} />
        <div className="flex flex-1 flex-col gap-6 p-4 md:p-6">
          <h1 className="text-heading-h2">Invoices</h1>
          <InvoicesTable />
        </div>
      </SidebarInset>
    </SidebarProvider>
  );
}

"use client";
import { BarChart3, Camera, Database, FileText, FolderKanban, Gauge, HelpCircle, LayoutDashboard, ListChecks, Search, Settings, Users } from "lucide-react";
import { Icon } from "@/components/ui/icon";
import {
  Sidebar, SidebarContent, SidebarFooter, SidebarGroup, SidebarGroupLabel, SidebarHeader, SidebarMenu, SidebarMenuButton,
  SidebarMenuItem, SidebarRail,
} from "@/components/ui/sidebar";
import { BrandHeader } from "@/components/brand-header";
import { NavSecondary } from "@/components/nav-secondary";
import { NavUser } from "@/components/nav-user";

const main = [
  { title: "Dashboard", icon: LayoutDashboard }, { title: "Lifecycle", icon: ListChecks }, { title: "Analytics", icon: BarChart3 },
  { title: "Projects", icon: FolderKanban }, { title: "Team", icon: Users },
];
const documents = [{ title: "Data library", icon: Database }, { title: "Reports", icon: FileText }, { title: "Capture", icon: Camera }];
const secondary = [{ title: "Settings", url: "#", icon: Settings }, { title: "Get help", url: "#", icon: HelpCircle }, { title: "Search", url: "#", icon: Search }];

/** The app sidebar the dashboard, settings and table blocks share. Pass the current page's title. */
export function DashboardSidebar({ current = "Dashboard", variant = "inset" }: { current?: string; variant?: "sidebar" | "inset" }) {
  return (
    <Sidebar collapsible="icon" variant={variant} label="Main navigation">
      <SidebarHeader>
        <BrandHeader name="Acme Inc" detail="Workspace" logo={Gauge} />
      </SidebarHeader>
      <SidebarContent>
        <nav aria-label="Main" className="contents">
          <SidebarGroup>
            <SidebarMenu>
              {main.map((m) => (
                <SidebarMenuItem key={m.title}>
                  <SidebarMenuButton href="#" isActive={m.title === current} tooltip={m.title}><Icon name={m.icon} /><span>{m.title}</span></SidebarMenuButton>
                </SidebarMenuItem>
              ))}
            </SidebarMenu>
          </SidebarGroup>
          <SidebarGroup>
            <SidebarGroupLabel as="h2">Documents</SidebarGroupLabel>
            <SidebarMenu>
              {documents.map((m) => (
                <SidebarMenuItem key={m.title}>
                  <SidebarMenuButton href="#" isActive={m.title === current} tooltip={m.title}><Icon name={m.icon} /><span>{m.title}</span></SidebarMenuButton>
                </SidebarMenuItem>
              ))}
            </SidebarMenu>
          </SidebarGroup>
          <NavSecondary items={secondary.map((s) => ({ ...s }))} className="mt-auto" />
        </nav>
      </SidebarContent>
      <SidebarFooter>
        <NavUser user={{ name: "Jane Cooper", email: "jane@acme.com" }} />
      </SidebarFooter>
      <SidebarRail />
    </Sidebar>
  );
}

"use client";
import { GalleryVerticalEnd, type LucideIcon } from "lucide-react";
import { Icon } from "@/components/ui/icon";
import { SidebarMenu, SidebarMenuButton, SidebarMenuItem } from "@/components/ui/sidebar";

/** Logo, product name and a second line (plan or version) at the top of the sidebar. Links home. */
export function BrandHeader({ name = "Acme Docs", detail = "v4.0.0", logo = GalleryVerticalEnd }: { name?: string; detail?: string; logo?: LucideIcon }) {
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <SidebarMenuButton href="#" size="lg" tooltip={name}>
          <span className="grid size-8 shrink-0 place-items-center rounded-control bg-brand text-fg-on-brand"><Icon name={logo} size={16} /></span>
          <span className="flex min-w-0 flex-1 flex-col">
            <span className="truncate text-label-medium text-fg-primary">{name}</span>
            <span className="truncate text-caption-default">{detail}</span>
          </span>
        </SidebarMenuButton>
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

"use client";
import type { LucideIcon } from "lucide-react";
import type { HTMLAttributes } from "react";
import { Icon } from "@/components/ui/icon";
import { SidebarGroup, SidebarGroupContent, SidebarMenu, SidebarMenuButton, SidebarMenuItem } from "@/components/ui/sidebar";

/** Small links near the bottom of the sidebar (support, feedback). */
export function NavSecondary({ items, ...rest }: HTMLAttributes<HTMLDivElement> & { items: { title: string; url: string; icon: LucideIcon }[] }) {
  return (
    <SidebarGroup {...rest}>
      <SidebarGroupContent>
        <SidebarMenu>
          {items.map((item) => (
            <SidebarMenuItem key={item.title}>
              <SidebarMenuButton href={item.url} size="sm" tooltip={item.title}>
                <Icon name={item.icon} size={16} />
                <span>{item.title}</span>
              </SidebarMenuButton>
            </SidebarMenuItem>
          ))}
        </SidebarMenu>
      </SidebarGroupContent>
    </SidebarGroup>
  );
}

"use client";
import { ChevronsUpDown } from "lucide-react";
import { Avatar } from "@/components/ui/display";
import { Icon } from "@/components/ui/icon";
import { Menu } from "@/components/ui/overlays";
import { SidebarMenu, SidebarMenuButton, SidebarMenuItem, useSidebar } from "@/components/ui/sidebar";

/** The signed-in person at the bottom of the sidebar, with an account menu. */
export function NavUser({ user }: { user: { name: string; email: string } }) {
  const { isMobile, state } = useSidebar();
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <Menu
          label={`Account menu for ${user.name}`}
          className="flex w-full"
          placement={!isMobile && state === "collapsed" ? "right-end" : "top-start"}
          items={[
            { label: "Profile", icon: "user" },
            { label: "Billing", icon: "credit-card" },
            { label: "Notifications", icon: "bell" },
            { label: "Sign out", icon: "sign-out", separatorBefore: true },
          ]}
          trigger={({ ref, ...p }) => (
            <SidebarMenuButton ref={ref as React.Ref<HTMLElement>} {...p} size="lg" tooltip={user.name}>
              <Avatar name={user.name} decorative />
              <span className="flex min-w-0 flex-1 flex-col">
                <span className="truncate text-label-medium text-fg-primary">{user.name}</span>
                <span className="truncate text-caption-default">{user.email}</span>
              </span>
              <Icon name={ChevronsUpDown} size={16} />
            </SidebarMenuButton>
          )}
        />
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

"use client";
import type { ReactNode } from "react";
import { Breadcrumbs } from "@/components/ui/nav-extra";
import { SidebarTrigger } from "@/components/ui/sidebar";

/** The bar above the page: sidebar toggle, breadcrumbs and optional actions on the end side. */
export function SiteHeader({ crumbs, actions }: { crumbs: { label: string; href?: string }[]; actions?: ReactNode }) {
  return (
    <header className="sticky top-0 z-[var(--ds-z-sticky)] flex h-14 shrink-0 items-center gap-2 border-b border-line-default bg-surface px-4 md:rounded-t-[inherit]">
      <SidebarTrigger className="-ms-1" />
      <span aria-hidden className="mx-1 h-4 w-px bg-line-default" />
      <Breadcrumbs items={crumbs} />
      {actions && <div className="ms-auto flex items-center gap-2">{actions}</div>}
    </header>
  );
}

"use client";
import { useState } from "react";
import { Columns3 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/feedback";
import { Icon } from "@/components/ui/icon";
import { Menu, Popover } from "@/components/ui/overlays";

type Invoice = { id: string; customer: string; issued: string; due: string; method: string; status: "Paid" | "Pending" | "Overdue"; amount: number };
const invoices: Invoice[] = [
  { id: "INV-001", customer: "North Farm Co.", issued: "Oct 1", due: "Oct 15", method: "Bank transfer", status: "Paid", amount: 250 },
  { id: "INV-002", customer: "Harbor Labs", issued: "Oct 2", due: "Oct 16", method: "Card", status: "Pending", amount: 150 },
  { id: "INV-003", customer: "Juniper Studio", issued: "Oct 3", due: "Oct 17", method: "Card", status: "Overdue", amount: 350 },
  { id: "INV-004", customer: "Acme Labs", issued: "Oct 5", due: "Oct 19", method: "Bank transfer", status: "Paid", amount: 450 },
  { id: "INV-005", customer: "Riverbend Foods", issued: "Oct 8", due: "Oct 22", method: "Card", status: "Paid", amount: 550 },
  { id: "INV-006", customer: "Summit Health", issued: "Oct 9", due: "Oct 23", method: "Bank transfer", status: "Pending", amount: 200 },
  { id: "INV-007", customer: "Kite & Co.", issued: "Oct 12", due: "Oct 26", method: "Card", status: "Paid", amount: 300 },
];
const tone = { Paid: "success", Pending: "warning", Overdue: "danger" } as const;
const money = (n: number) => n.toLocaleString("en-US", { style: "currency", currency: "USD" });
const cols = [
  { key: "customer", label: "Customer" }, { key: "issued", label: "Issued" }, { key: "due", label: "Due" },
  { key: "method", label: "Method" }, { key: "status", label: "Status" },
] as const;
type ColKey = (typeof cols)[number]["key"];

export function InvoicesTable() {
  const [visible, setVisible] = useState<Set<ColKey>>(new Set(["customer", "due", "method", "status"]));
  const show = cols.filter((c) => visible.has(c.key));
  const th = "h-10 border-b border-line-default bg-surface-subtle px-4 text-label-small text-fg-secondary";
  const td = "h-12 border-b border-line-default px-4 text-body-small";
  return (
    <div className="flex flex-col gap-3">
      <div className="flex flex-wrap items-center justify-end gap-2">
        <Popover
          title="Columns"
          placement="bottom"
          width={220}
          trigger={({ ref, ...p }) => (
            <button ref={ref} type="button" {...p} className="inline-flex h-control-sm items-center gap-2 rounded-control border border-line-strong bg-surface px-3 text-label-medium hover:bg-neutral-hover focus-visible:focus-ring">
              <Icon name={Columns3} size={16} />Columns
            </button>
          )}
        >
          <fieldset className="flex flex-col gap-2">
            <legend className="sr-only">Show columns</legend>
            {cols.map((c) => (
              <label key={c.key} className="flex items-center gap-2 text-body-small">
                <input type="checkbox" checked={visible.has(c.key)} onChange={(e) => setVisible((v) => { const n = new Set(v); if (e.target.checked) n.add(c.key); else n.delete(c.key); return n; })} className="size-4 accent-[var(--ds-color-bg-brand)]" />
                {c.label}
              </label>
            ))}
          </fieldset>
        </Popover>
        <Button size="sm" variant="secondary" leadingIcon="download">Export CSV</Button>
      </div>
      <div className="relative overflow-x-auto rounded-container border border-line-default bg-surface" tabIndex={0} role="region" aria-label="Invoices table, scrolls sideways">
        <table className="w-full min-w-[640px] border-separate border-spacing-0">
          <caption className="sr-only">Invoices, October 2026</caption>
          <thead>
            <tr>
              <th scope="col" className={`${th} text-start`}>Invoice</th>
              {show.map((c) => <th key={c.key} scope="col" className={`${th} text-start`}>{c.label}</th>)}
              <th scope="col" className={`${th} text-end`}>Amount</th>
              <th scope="col" className={th}><span className="sr-only">Actions</span></th>
            </tr>
          </thead>
          <tbody>
            {invoices.map((inv, i) => (
              <tr key={inv.id} className="hover:bg-neutral-hover">
                <th scope="row" className={`${td} text-start font-mono text-code-small font-normal`}>{inv.id}</th>
                {show.map((c) => <td key={c.key} className={td}>{c.key === "status" ? <Badge tone={tone[inv.status]}>{inv.status}</Badge> : inv[c.key]}</td>)}
                <td className={`${td} text-end tabular-nums`}>{money(inv.amount)}</td>
                <td className={`${td} w-14`}>
                  <Menu label={`More actions for ${inv.id}`} placement={i < 3 ? "bottom-end" : "top-end"} items={[{ label: "View invoice", icon: "eye" }, { label: "Download PDF", icon: "download" }, { label: "Send reminder", icon: "send", disabled: inv.status === "Paid" }, { label: "Void invoice", icon: "x-circle", tone: "danger", separatorBefore: true }]} />
                </td>
              </tr>
            ))}
          </tbody>
          <tfoot>
            <tr>
              <th scope="row" colSpan={show.length + 1} className="h-12 px-4 text-start text-label-medium">Total</th>
              <td className="h-12 px-4 text-end text-label-medium tabular-nums">{money(invoices.reduce((s, i) => s + i.amount, 0))}</td>
              <td />
            </tr>
          </tfoot>
        </table>
      </div>
    </div>
  );
}
